  "claims": [
    {
      "claim": "The closest structural context, the 2-halogenated adenine nucleoside cladribine, has measured absolute oral bioavailability of 36–46% in fasted patients, clearly above the 20% threshold.",
      "card_ids": ["C07","C11","C17"]
    },
    {
      "claim": "Other nucleoside analog contexts consistently exceed 20%: zalcitabine 80% in humans and 30% in mice, lamivudine 69–93%, emtricitabine 92%, and didanosine 22–28%.",
      "card_ids": ["C18","C29","C03","C06","C16","C20","C25","C26","C19","C30","C02","C09"]
    },
    {
      "claim": "L3 oral exposure records for related nucleoside/nucleotide analogs show measurable oral AUC and Cmax after oral dosing (e.g., lamivudine AUC0-t 12.9 µg·h/mL and Cmax 2.4 µg/mL; tenofovir Cmax 327.9 ng/mL), consistent with meaningful oral absorption.",
      "card_ids": ["C32","C34","C38","C41","C31","C35"]
    },
    {
      "claim": "No affirmative threshold-relevant evidence supports F < 20% for the query; the low paliperidone outcomes arise from a different structural class and modified-release formulation context and are not transferable.",
      "card_ids": ["C01","C21","C27","C28"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C31","C32","C33","C34","C35","C36","C37","C38","C39","C40","C41","C42"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the exact query molecule.",
    "The query's pyranose sugar differs from cladribine's deoxyribose, which may affect transporter affinity and first-pass metabolism.",
    "No fed/fasted condition, formulation, or dose information is available for the query.",
    "Permeability and nucleoside transporter involvement are not directly measured for the query.",
    "The intended species is unspecified; zalcitabine shows species-dependent F (80% human vs 30% mouse), though both exceed 20%.",
    "L3 records are for related nucleosides/nucleotides, not the query, and report exposure rather than absolute bioavailability."
  ],
  "decision_summary": "The query is a polar 2-fluoroadenine nucleoside analog. The most relevant training contexts—especially cladribine (36–46%) and other nucleoside analogs (zalcitabine 80%, lamivudine 69–93%, emtricitabine 92%, didanosine 22–28%)—all support absolute oral bioavailability at or above 20%. New L3 oral exposure records for related nucleosides are consistent with meaningful oral absorption and do not contradict this. No affirmative evidence supports F < 20%. Therefore the prediction is high, with moderate confidence due to the absence of a direct query-specific measurement and structural differences in the sugar moiety."
}

